            .ok_or_else(|| format!("Operit1 角色卡绑定了不存在的用户偏好：{profileId}"))?;
        let markdown = buildOperit2UserMarkdown(profile)?;
        appendSharedUserMarkdown(self.storageHost.as_ref(), &profileId, &markdown)?;
    }
    Ok(())
}

