/// Only remap media that the original exporter actually included in this snapshot.
fn forSnapshot(parsed: &ParsedOperit1Snapshot, paths: &RuntimeStorePaths) -> Result<Self, String> {
    let mut plan = Self::new();
    plan.legacyPackageName = parsed.archive.manifest.packageName.clone();
    let importId = Uuid::new_v4().to_string();
    // Import APIs upsert by ID; allocate new identities before any persistent writes.
    let mut cardNames = CharacterCardManager::new(paths.clone()).getAllCharacterCards()
        .map_err(|error| error.to_string())?.into_iter()
        .map(|card| card.name.trim().to_string()).collect::<HashSet<_>>();
    if let Some(preferences) = parsed.archive.datastorePreferences.get(ENTRY_CHARACTER_CARDS) {
        for id in optionalPreferenceStringSet(preferences, "character_card_list")? {
            let name = requiredPreferenceString(preferences, &format!("character_card_{id}_name"),
                &format!("Operit1 角色卡缺少名称：{id}"))?;
            let targetName = uniqueOperit1ImportName(name, &mut cardNames);
            if id == CharacterCardManager::DEFAULT_CHARACTER_CARD_ID {
                plan.defaultCharacterName = Some(targetName.clone());
            }
            plan.characterNames.insert(name.to_string(), targetName);
            plan.characterIds.insert(id, Uuid::new_v4().to_string());
        }
    }
    let mut groupNames = CharacterGroupCardManager::new(paths.clone()).getAllCharacterGroupCards()
        .map_err(|error| error.to_string())?.into_iter()
        .map(|group| group.name.trim().to_string()).collect::<HashSet<_>>();
    for group in buildOperit2CharacterGroups(parsed)? {
        plan.groupNames.insert(group.id.clone(), uniqueOperit1ImportName(&group.name, &mut groupNames));
        plan.groupIds.insert(group.id, Uuid::new_v4().to_string());
    }
    let mut memoryNames = SharedMemoryStoreManager::new(paths.clone()).getAllSharedMemoryStores()
        .map_err(|error| error.to_string())?.into_iter()
        .map(|store| store.name.trim().to_string()).collect::<HashSet<_>>();
    for profileId in collectOperit1MemoryProfileIds(parsed)? {
        let sourceId = operit1SharedMemoryStoreId(&profileId);
        plan.memoryStoreIds.insert(sourceId.clone(), Uuid::new_v4().to_string());
        plan.memoryStoreNames.insert(sourceId,
            uniqueOperit1ImportName(&operit1SharedMemoryStoreName(parsed, &profileId)?, &mut memoryNames));
    }
    plan.importedFilesRoot.push_str(&format!("/{importId}"));
    plan.importedExternalFilesRoot.push_str(&format!("/{importId}"));
    let mut copyPlan = buildSnapshotFileCopyPlan(parsed)?;
    for sourceId in &copyPlan.workspaceIds {
        plan.workspaceIds.insert(sourceId.clone(), Uuid::new_v4().to_string());
    }
    for item in &mut copyPlan.items {
        if let Some(relative) = item.sourceEntry.strip_prefix(ENTRY_WORKSPACE_FILES_PREFIX) {
            let (id, rest) = splitWorkspaceRelativePath(relative)?;
            let targetId = &plan.workspaceIds[id];
            item.targetPath = format!("{WORKSPACE_DIR_PATH}/{targetId}/{rest}");
        } else if let Some(relative) = item.sourceEntry.strip_prefix(ENTRY_FILES_PREFIX) {
            item.targetPath = joinVirtualPath(&plan.importedFilesRoot, relative);
        } else if let Some(relative) = item.sourceEntry.strip_prefix(ENTRY_EXTERNAL_FILES_PREFIX) {
            item.targetPath = joinVirtualPath(&plan.importedExternalFilesRoot, relative);
        }
    }
    copyPlan.workspaceIds = plan.workspaceIds.values().cloned().collect();
    let packageName = &parsed.archive.manifest.packageName;
    for item in &copyPlan.items {
        let (prefixes, relative) = if let Some(relative) = item.sourceEntry.strip_prefix(ENTRY_FILES_PREFIX) {
            (vec![format!("/data/user/0/{packageName}/files/"), format!("/data/data/{packageName}/files/")], relative)
        } else if let Some(relative) = item.sourceEntry.strip_prefix(ENTRY_EXTERNAL_FILES_PREFIX) {
            (vec![format!("/storage/emulated/0/Android/data/{packageName}/files/"), format!("/sdcard/Android/data/{packageName}/files/")], relative)
        } else {
            continue;
        };
        let target = if let Some(relative) = item.sourceEntry.strip_prefix(ENTRY_WORKSPACE_FILES_PREFIX) {
            let (id, rest) = splitWorkspaceRelativePath(relative)?;
            paths.workspace_path(&plan.workspaceIds[id]).join(rest).to_string_lossy().into_owned()
        } else {
            paths.runtime_storage_path(&item.targetPath).to_string_lossy().into_owned()
        };
        for prefix in prefixes {
            let path = format!("{prefix}{relative}");
            plan.resourcePaths.push((format!("file://{path}"), target.clone()));
            plan.resourcePaths.push((path, target.clone()));
        }
    }
    // Replace longer names first so one attachment cannot consume another name's prefix.
    plan.resourcePaths.sort_by(|left, right| right.0.len().cmp(&left.0.len()));
    plan.copyPlan = Some(copyPlan);
    Ok(plan)
}

fn rewriteMessageContent(&self, content: &str) -> String {
    if !content.contains("/data/") && !content.contains("/Android/data/") {
        return content.to_string();
    }
    let mut rewritten = content.to_string();
    for (source, target) in &self.resourcePaths {
        let mut output = String::with_capacity(rewritten.len());
        let mut copied = 0;
        for (start, _) in rewritten.match_indices(source) {
            let end = start + source.len();
            let boundary = rewritten[end..].chars().next();
            if boundary.is_some_and(|value| !value.is_whitespace() && !matches!(value, '\'' | '"' | '<' | '>' | ')' | ']' | '}')) {
                continue;
            }
            output.push_str(&rewritten[copied..start]);
            output.push_str(target);
            copied = end;
        }
        output.push_str(&rewritten[copied..]);
        rewritten = output;
    }
    rewritten
}

